import test, { afterEach } from 'node:test'
import assert from 'node:assert/strict'
import { useFakeSettings, stubMeson, makeWorld, swapId, swapRecord, encodedSwap, json, sleep, texts, MOVING, DONE } from './helpers.mjs'

useFakeSettings()
const { stopWatchingChannel } = await import('../src/watch.js')
const { forgetTicket } = await import('../src/ticket-state.js')
const { recoverTickets } = await import('../src/recover.js')
const { onTicketMessage } = await import('../src/tickets.js')
const { buildSwapEmbed, buildProcessingMessage, buildOutcomeMessage, buildOutageNotice } = await import('../src/render.js')
const { lookupSwap, getSwaps } = await import('../src/meson.js')

afterEach(() => { for (let i = 1; i <= 12; i++) stopWatchingChannel(`r${i}`) })

// =============================================================================
//   Helpers
// =============================================================================

/**
 * A fake Meson whose explorer can be switched off (`meson.down`), or only its wallet list (`meson.walletDown`, as on 2026-11-10): it then answers with an HTML error page, as in the outage of 2026-11-10, while the relayer knows each swap in `relayer` (by swap ID) under its source hash.
 * @param {{events: Record<string, object[]>, relayer: Record<string, {hash: string, steps: Record<string, string>}>, search?: Record<string, object>}} world `search` as for stubMeson, for once the explorer is back
 */
function stubOutage ({ events = {}, relayer = {}, search = {}, walletSwaps = [] }) {
  stubMeson({ events, search, walletSwaps })
  const explorer = globalThis.fetch
  const meson = { down: true, walletDown: false, relayerRequests: 0 }
  globalThis.fetch = async (url) => {
    const u = String(url)
    if (u.includes('relayer.meson.fi')) {
      meson.relayerRequests++
      for (const [id, r] of Object.entries(relayer)) {
        if (u.endsWith(`/swap/${id}`) || u.endsWith(`?hash=${r.hash}`)) {
          return json({ result: { ...r.steps, swap: { id, encoded: encodedSwap(), from: { amount: '5', network: 'bnb', token: 'usdt' }, to: { amount: '4.9', network: 'sol', token: 'usdt' } } } })
        }
      }
      return json({ error: { code: -1, message: 'swap-not-found' } }, 404)
    }
    if ((meson.down && u.includes('explorer.meson.fi')) || (meson.walletDown && u.includes('/address/'))) return new Response('<html>Internal Server Error</html>', { status: 500 })
    return explorer(url)
  }
  return meson
}

/** The bot's details embeds in a channel, as they are now (edits included). */
const detailEmbeds = (world) => world.channel.history.map((m) => m.embeds?.[0]?.data ?? m.embeds?.[0]).filter((e) => e?.title?.startsWith('Meson swap'))

/** An embed as plain data, with Discord timestamps blanked (the fake Meson stamps each answer with the time it was asked). */
const plain = (embed) => JSON.parse(JSON.stringify(embed).replace(/<t:\d+:/g, '<t:N:'))

/** The details embed the normal flow (explorer up all along) shows for this swap after an update — what a limited embed must turn into, field for field. */
const normalEmbed = async (id) => plain(buildSwapEmbed((await getSwaps([id])).get(id), { sourceNote: 'auto-detected from this ticket · auto-updated', updatesHere: true }).data)

/** The normal closing message for this swap as Meson has it now. */
const normalClosing = async (id) => buildOutcomeMessage((await getSwaps([id])).get(id))

// =============================================================================
//   Relayer stand-in
// =============================================================================

test('with the explorer down, a hash gets a limited embed and no ⏳ — once it is back, the normal embed, ⏳ and closing message follow', async () => {
  const id = swapId('e')
  const hash = '0x' + '7'.repeat(64)
  const events = { [id]: MOVING }
  const meson = stubOutage({ events, relayer: { [id]: { hash, steps: { POSTED: '0xaa' } } } })
  const world = makeWorld('r1')
  onTicketMessage(world.message(1, world.user, { content: `my hash ${hash}` }))
  await sleep(300)

  const [limited] = detailEmbeds(world)
  assert.equal(limited.title, 'Meson swap — Status unavailable (limited details)')
  const field = (name) => limited.fields.find((f) => f.name === name)?.value
  assert.ok(field('⚠️ Limited details').includes('This message will update automatically once it\'s back'))
  assert.ok(field('From').includes('wallet not available'))
  assert.ok(field('Amount').includes('→ 4.9'), 'the received amount comes from the relayer')
  assert.ok(field('Transactions found so far (may still be confirming)'))
  assert.equal(field('Timing'), undefined)
  assert.equal(texts(world.posted).filter(Boolean).length, 0, 'no ⏳ while the status is unknown')

  meson.down = false
  await sleep(1500)
  assert.deepEqual(plain(detailEmbeds(world)[0]), await normalEmbed(id), 'once the explorer is back, the embed is exactly the normal one')
  assert.deepEqual(texts(world.posted).filter(Boolean), [buildProcessingMessage()], 'and gets the normal ⏳')

  events[id] = DONE
  await sleep(2500)
  assert.deepEqual(plain(detailEmbeds(world)[0]), await normalEmbed(id))
  assert.deepEqual(texts(world.posted).filter(Boolean), [buildProcessingMessage(), await normalClosing(id)], 'then the normal closing message')
  assert.equal(world.channel.history.find((m) => m.content?.startsWith('⏳')).deleted, true, 'which takes the ⏳ down, as usual')
  assert.equal(world.posted.filter((p) => p.embeds).length, 1, 'never a second embed')
})

test('a swap the relayer would call Done never shows Done until the explorer confirms it', async () => {
  const id = swapId('f')
  const meson = stubOutage({ events: { [id]: DONE }, relayer: { [id]: { hash: '0x' + '8'.repeat(64), steps: { EXECUTED: '0xaa', RELEASED: '0xbb' } } } })
  const world = makeWorld('r2')
  onTicketMessage(world.message(1, world.user, { content: `swap ${id}` }))
  await sleep(300)
  const [limited] = detailEmbeds(world)
  assert.equal(limited.title, 'Meson swap — Status unavailable (limited details)')
  assert.equal(limited.description, undefined, 'no status reason either')
  assert.ok(!/done|complete|released to the recipient/i.test(JSON.stringify(limited)), 'nothing claims the swap is finished')
  assert.equal(texts(world.posted).filter(Boolean).length, 0, 'no closing message from the relayer')

  meson.down = false
  await sleep(1500)
  assert.deepEqual(plain(detailEmbeds(world)[0]), await normalEmbed(id))
  assert.deepEqual(texts(world.posted).filter(Boolean), [await normalClosing(id)], 'only the normal closing message, no ⏳ first')
})

test('a value the relayer does not know either gets the outage notice once while it is retried, never "couldn\'t find"', async () => {
  const id = swapId('d')
  const meson = stubOutage({ events: { [id]: MOVING }, relayer: {}, search: { [id]: { swapId: id } } })
  const world = makeWorld('r3')
  onTicketMessage(world.message(1, world.user, { content: `swap ${id}` }))
  await sleep(2500) // several retries
  assert.deepEqual(texts(world.posted), [buildOutageNotice('swap')], 'one notice, however many retries')
  assert.ok(meson.relayerRequests > 1)
  meson.down = false
  await sleep(1500)
  assert.equal(detailEmbeds(world).length, 1)
  assert.ok(!detailEmbeds(world)[0].title.includes('limited'))
})

test('after a restart, a limited embed becomes the normal one and gets the ⏳ it never had', async () => {
  const id = swapId('c')
  const meson = stubOutage({ events: { [id]: MOVING }, relayer: {} })
  meson.down = false
  const world = makeWorld('r4')
  const embed = world.message(10, world.me, { embeds: [{ title: 'Meson swap — Status unavailable (limited details)', url: `https://explorer.meson.fi/swap/${id}` }] })
  world.channel.history = [embed]
  forgetTicket('r4')
  await recoverTickets(world.client)
  await sleep(200)
  assert.deepEqual(plain(embed.embeds[0].data), await normalEmbed(id))
  assert.deepEqual(texts(world.posted), [buildProcessingMessage()])
})

test('after a restart, a full embed with its ⏳ gets no second one', async () => {
  const id = swapId('b')
  stubOutage({ events: { [id]: MOVING }, relayer: {} }).down = false
  const world = makeWorld('r5')
  world.channel.history = [
    world.message(10, world.me, { embeds: [{ title: 'Meson swap — Bonded', url: `https://explorer.meson.fi/swap/${id}` }] }),
    world.message(11, world.me, { content: '⏳ x', reference: { messageId: '10' } }),
  ]
  await recoverTickets(world.client)
  await sleep(200)
  assert.equal(world.posted.length, 0)
})

test('/meson-query (not followed) says to look again later rather than promising an update', async () => {
  const id = swapId('a')
  stubOutage({ events: {}, relayer: { [id]: { hash: '0x' + '9'.repeat(64), steps: { POSTED: '0xaa' } } } })
  const swap = await lookupSwap(id)
  assert.equal(swap.limited, true)
  assert.equal(swap.from.address, null)
  const notice = buildSwapEmbed(swap).data.fields.find((f) => f.name === '⚠️ Limited details').value
  assert.ok(notice.includes('Look the swap up again later'))
})

test('a value the relayer does not know does not hold back a later one it does know', async () => {
  const id = swapId('9')
  const hash = '0x' + '6'.repeat(64)
  const typo = swapId('8')
  const meson = stubOutage({ events: { [id]: MOVING }, relayer: { [id]: { hash, steps: { POSTED: '0xaa' } } }, search: { [hash]: { swapId: id } } })
  const world = makeWorld('r6')
  // The swap ID comes first in the lookup order, the chain explorer link after it.
  onTicketMessage(world.message(1, world.user, { content: `my swap id ${typo} and the tx https://arbiscan.io/tx/${hash}` }))
  await sleep(300)
  assert.equal(detailEmbeds(world).length, 1, 'the link gets its limited embed straight away')
  assert.equal(detailEmbeds(world)[0].title, 'Meson swap — Status unavailable (limited details)')
  assert.equal(texts(world.posted).filter(Boolean).length, 0, 'no "couldn\'t find" for the typo while Meson cannot answer')

  meson.down = false
  await sleep(1500)
  assert.deepEqual(plain(detailEmbeds(world)[0]), await normalEmbed(id))
  assert.deepEqual(texts(world.posted).filter(Boolean), [buildProcessingMessage()], 'the retry adds no "couldn\'t find" next to the shown swap')
  assert.equal(world.posted.filter((p) => p.embeds).length, 1, 'and no second embed')
})

// =============================================================================
//   Outage notices
// =============================================================================

test('a wallet whose swap list Meson cannot read gets the wallet notice once — and its list once Meson is back', async () => {
  const wallet = '0x' + '7c'.repeat(20)
  const meson = stubOutage({ walletSwaps: [swapRecord(swapId('4'), MOVING)] })
  meson.down = false
  meson.walletDown = true
  const world = makeWorld('r7')
  onTicketMessage(world.message(1, world.user, { content: `my wallet ${wallet}` }))
  await sleep(2500) // several retries
  assert.deepEqual(texts(world.posted), [buildOutageNotice('wallet')])
  meson.walletDown = false
  await sleep(1500)
  assert.equal(world.posted.length, 2)
  assert.ok(world.posted[1].embeds[0].data.title.startsWith('Unfinished Meson swaps for this wallet'))
})

test('the form\'s wallet gets the wallet notice too (accepted on the shared server), but its swap-shaped noise gets no notice', async () => {
  const wallet = '0x' + '7d'.repeat(20)
  const meson = stubOutage({})
  meson.down = false
  meson.walletDown = true
  const form = makeWorld('r8')
  onTicketMessage(form.message(1, { id: 'TICKETTOOL', bot: true }, { embeds: [{ description: `Wallet: ${wallet}` }] }))
  await sleep(300)
  assert.deepEqual(texts(form.posted), [buildOutageNotice('wallet')])

  meson.down = true
  const noise = makeWorld('r9')
  onTicketMessage(noise.message(1, { id: 'TICKETTOOL', bot: true }, { embeds: [{ description: `Ref: ${swapId('5')}` }] }))
  await sleep(300)
  assert.equal(noise.posted.length, 0, 'as it gets no "couldn\'t find"')
  // Meson back, so the retries end.
  meson.down = false
  meson.walletDown = false
  await sleep(1500)
  assert.equal(form.posted.length, 1, 'a wallet that has never used Meson still gets nothing more')
})

test('after a restart, an outage notice already posted is not posted again', async () => {
  const id = swapId('6')
  const meson = stubOutage({ events: { [id]: MOVING } })
  const world = makeWorld('r10')
  world.channel.history = [
    world.message(1, world.user, { content: `swap ${id}` }),
    world.message(2, world.me, { content: buildOutageNotice('swap'), reference: { messageId: '1' } }),
    world.message(3, world.user, { content: `still waiting, ${swapId('7')}` }),
  ]
  forgetTicket('r10')
  await recoverTickets(world.client)
  await sleep(300)
  assert.equal(world.posted.length, 0)
  // Meson back, so the retries end.
  meson.down = false
  await sleep(1500)
})
